<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {getInquiryClient,rpc,states,sheetUrl,formatDate,googleLoginAvailable} from './inquiry-client.js'
const props=defineProps({callback:Boolean})
const busy=ref(false),session=ref(null),allowed=ref(false),message=ref(''),rows=ref([]),selected=ref(null),history=ref([]),conflicts=ref([]),notifications=ref([]),search=ref(''),filter=ref(''),editState=ref('신규'),memo=ref(''),page=ref(0),hasNext=ref(false)
let subscription,timer
const googleReady=ref(false)
const registration=ref(null),acceptUse=ref(false)
const shown=computed(()=>rows.value)
function fail(e){message.value=e.message||'요청을 처리하지 못했습니다.'}
async function verify(){allowed.value=false;rows.value=[];selected.value=null;registration.value=null;if(!session.value)return;registration.value=await rpc('inquiry_admin_registration');allowed.value=await rpc('is_admin');if(allowed.value)await load();else message.value=registration.value?.eligible?'관리자 이용 확인 또는 운영자의 관리자 등록이 필요합니다.':'관리자 권한이 확인되지 않았습니다. 승인된 Google 계정으로 로그인해 주십시오.'}
async function confirmUse(){busy.value=true;try{if(!acceptUse.value)return;await rpc('accept_signup',{p_version:registration.value.version});await verify()}catch(e){fail(e)}finally{busy.value=false}}
async function load(){busy.value=true;try{const data=await rpc('admin_list_inquiries',{p_search:search.value,p_status:filter.value,p_offset:page.value*50});hasNext.value=data.length>50;rows.value=data.slice(0,50);message.value=''}catch(e){fail(e)}finally{busy.value=false}}
async function find(){page.value=0;await load()}
async function open(row){selected.value=null;try{const data=await rpc('admin_inquiry_detail',{p_id:row.id});selected.value=data.inquiry;history.value=data.history;conflicts.value=data.conflicts;notifications.value=data.notifications;editState.value=data.inquiry.status;memo.value=data.inquiry.admin_memo;window.history.replaceState(null,'','#'+row.id)}catch(e){fail(e)}}
async function login(){busy.value=true;try{googleReady.value=await googleLoginAvailable();if(!googleReady.value)throw Error('Google 로그인 연결을 준비하고 있습니다.');const {error}=await getInquiryClient().auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/admin/callback.html',queryParams:{prompt:'select_account'}}});if(error)throw error}catch(e){fail(e);busy.value=false}}
async function logout(){allowed.value=false;rows.value=[];selected.value=null;history.value=[];conflicts.value=[];notifications.value=[];await getInquiryClient().auth.signOut();session.value=null;window.history.replaceState(null,'',location.pathname)}
async function save(){busy.value=true;try{const data=await rpc('admin_update_inquiry',{p_id:selected.value.id,p_version:selected.value.version,p_status:editState.value,p_memo:memo.value});if(data.conflict){message.value='同時 수정이 감지되었습니다. 아래 충돌 내용을 확인해 주십시오.'.replace('同時','동시');await open(selected.value)}else{await open(data);await load();message.value='저장했습니다.'}}catch(e){fail(e)}finally{busy.value=false}}
async function resolve(conflict,choice){busy.value=true;try{await rpc('admin_resolve_inquiry_conflict',{p_conflict:conflict.id,p_version:selected.value.version,p_choice:choice});await open(selected.value);await load();message.value='충돌 해결 내용을 기록했습니다.'}catch(e){fail(e)}finally{busy.value=false}}
onMounted(async()=>{try{googleReady.value=await googleLoginAvailable();const c=getInquiryClient();if(!googleReady.value)message.value='Google 로그인 연결을 준비하고 있습니다.';if(props.callback){const code=new URLSearchParams(location.search).get('code');if(!code)throw Error('로그인이 취소되었거나 확인 코드가 없습니다.');const {error}=await c.auth.exchangeCodeForSession(code);window.history.replaceState(null,'','/admin/');if(error)throw error}const {data,error}=await c.auth.getSession();if(error)throw error;session.value=data.session;await verify();if(allowed.value&&/^#[0-9a-f-]{36}$/.test(location.hash))await open({id:location.hash.slice(1)});subscription=c.auth.onAuthStateChange((event,s)=>{session.value=s;if(event==='SIGNED_OUT'){allowed.value=false;rows.value=[];selected.value=null;history.value=[];notifications.value=[];conflicts.value=[]}}).data.subscription;timer=setInterval(async()=>{if(!session.value||!allowed.value)return;try{if(!await rpc('is_admin')){allowed.value=false;rows.value=[];selected.value=null;history.value=[];notifications.value=[];conflicts.value=[];message.value='관리자 권한이 만료되었습니다.'}}catch{}},60000)}catch(e){fail(e)}})
onUnmounted(()=>{subscription?.unsubscribe();clearInterval(timer)})
</script>
<template><main class="inquiry-admin"><header><div><span class="consult-eyebrow">PMOFFICE ADMIN</span><h1>고객 문의 관리</h1><p>접수 내용을 확인하고 상담 진행 상황을 관리합니다.</p></div><div class="actions" v-if="allowed"><a class="btn secondary" :href="sheetUrl" target="_blank" rel="noopener">Google 관리대장 ↗</a><button class="btn secondary" @click="logout">로그아웃</button></div></header>
<p role="status" aria-live="polite">{{message}}</p>
<section v-if="!allowed" class="admin-login"><h2>관리자 로그인</h2><p>승인된 Google 계정으로 로그인해 주십시오.</p><button v-if="!session" class="btn primary" :disabled="busy||!googleReady" @click="login">Google로 로그인</button><button v-else class="btn secondary" @click="logout">다른 계정으로 로그인</button><form v-if="registration?.eligible&&!registration.accepted" @submit.prevent="confirmUse"><label class="admin-accept"><input v-model="acceptUse" type="checkbox" required>승인된 관리자 계정으로 문의 관리 기능을 사용하겠습니다.</label><button class="btn primary" :disabled="busy||!acceptUse">관리자 이용 확인</button></form></section>
<template v-else><form class="admin-filters" @submit.prevent="find"><label>문의 검색<input v-model="search" maxlength="120" placeholder="회사, 이름, 이메일, 문의 내용"></label><label>처리 상태<select v-model="filter"><option value="">전체</option><option v-for="s in states" :key="s">{{s}}</option></select></label><button class="btn primary" :disabled="busy">검색·새로고침</button></form>
<div class="admin-columns"><section><h2>문의 목록</h2><p v-if="!shown.length">표시할 문의가 없습니다.</p><div class="admin-list"><button v-for="r in shown" :key="r.id" class="admin-row" :aria-pressed="selected?.id===r.id" @click="open(r)"><span class="admin-badge">{{r.status}}</span><strong>{{r.company}} · {{r.person}}</strong><span>{{r.service}} · {{formatDate(r.created_at)}}</span><small>{{r.receipt}} · 시트 {{r.sync_status}}</small></button></div><div class="actions"><button :disabled="page===0||busy" @click="page--;load()">이전</button><span>{{page+1}} 페이지</span><button :disabled="!hasNext||busy" @click="page++;load()">다음</button></div></section>
<section v-if="selected" class="admin-detail"><h2>{{selected.company}}</h2><p>{{selected.receipt}} · {{formatDate(selected.created_at)}}</p><dl><template v-for="(label,key) in {person:'이름과 직함',email:'이메일',phone:'전화번호',service:'관심 분야',course:'교육 과정',message:'문의 내용',environment:'필요 산출물·사용 환경',timing:'희망 일정',source:'유입 페이지'}" :key="key"><dt>{{label}}</dt><dd>{{selected[key]||'미입력'}}</dd></template></dl>
<form @submit.prevent="save"><label>처리 상태<select v-model="editState"><option v-for="s in states" :key="s">{{s}}</option></select></label><label>관리자 메모<textarea v-model="memo" rows="5" maxlength="5000"></textarea></label><button class="btn primary" :disabled="busy">변경 저장</button></form>
<section v-if="conflicts.length"><h3>동시 수정 확인</h3><article v-for="c in conflicts" :key="c.id" class="admin-conflict"><p>{{formatDate(c.created_at)}} · {{c.source}}</p><p>현재 서버: {{selected.status}} / {{selected.admin_memo}}</p><p>수정 요청: {{c.requested_status}} / {{c.requested_memo}}</p><div class="actions"><button :disabled="busy" @click="resolve(c,'server')">서버 값 유지</button><button :disabled="busy" @click="resolve(c,'incoming')">시트·수정 요청 값 적용</button></div></article></section>
<h3>시트 동기화</h3><p>{{selected.sync_status}} · 데이터 버전 {{selected.version}}</p><h3>이메일 알림</h3><ul><li v-for="n in notifications" :key="n.recipient">{{n.recipient}}: {{n.state}}<span v-if="n.error"> · {{n.error}}</span></li></ul><h3>처리 이력</h3><ol><li v-for="h in history" :key="h.id">{{formatDate(h.created_at)}} · {{h.source}} · {{h.before_status||'접수'}} → {{h.after_status}}<p v-if="h.before_memo||h.after_memo">{{h.before_memo}} → {{h.after_memo}}</p></li></ol></section><section v-else class="admin-detail"><p>목록에서 문의를 선택해 주십시오.</p></section></div></template></main></template>
<style scoped>.inquiry-admin{max-width:1380px;margin:0 auto;padding:80px 32px;color:#102b4e}.inquiry-admin header{display:flex;justify-content:space-between;align-items:center;gap:24px}.inquiry-admin h1{font-size:36px;font-weight:800;line-height:1.3}.inquiry-admin h2{font-size:23px;font-weight:700;margin:18px 0}.inquiry-admin h3{font-size:18px;font-weight:700;margin:24px 0 12px}.inquiry-admin p{margin:12px 0}.admin-accept{display:flex!important;align-items:center;gap:10px}.admin-accept input{width:20px!important}.admin-login,.admin-detail{border:1px solid #d5deed;border-radius:16px;padding:28px}.admin-filters{display:flex;gap:16px;align-items:end;margin:30px 0}.inquiry-admin label{display:grid;gap:8px;flex:1;margin-bottom:18px}.inquiry-admin input,.inquiry-admin select,.inquiry-admin textarea{border:1px solid #aebed4;border-radius:8px;background:white;color:#102b4e;padding:12px;min-width:0;width:100%}.admin-columns{display:grid;grid-template-columns:minmax(260px,.8fr) minmax(0,1.3fr);gap:28px}.admin-list{display:grid;gap:12px}.admin-row{text-align:left;border:1px solid #d5deed;border-radius:12px;padding:18px;display:grid;gap:8px;background:white;overflow-wrap:anywhere}.admin-row[aria-pressed=true]{border:2px solid #285cf0}.admin-badge{font-size:13px;color:#315fe3}.admin-detail dd{white-space:pre-wrap;overflow-wrap:anywhere;margin:4px 0 18px}.admin-detail dt{font-weight:700}.admin-detail li{overflow-wrap:anywhere}.inquiry-admin .actions{display:flex;gap:14px;flex-wrap:wrap;align-items:center;margin:18px 0}.admin-conflict{padding:16px;background:#fff7e5;border-radius:8px}.inquiry-admin button:disabled{opacity:.5;cursor:wait}.inquiry-admin button:focus-visible,.inquiry-admin a:focus-visible{outline:3px solid #295fea;outline-offset:3px}@media(max-width:768px){.inquiry-admin{padding:60px 20px}.inquiry-admin header,.admin-filters{display:block}.admin-columns{grid-template-columns:1fr}.admin-detail{padding:20px}.inquiry-admin h1{font-size:30px}}</style>


